"""Definitive randomized full-model timing, with per-condition bounded verdicts."""
import numpy as np

def add(lines,verdict):
    from reporting import completed,evidence
    runs=completed('interleaved-runtime','interleaved_runtime_results.json')
    if not runs:return {}
    path,data=runs[-1];summary=[];positive=[];negative=[];uncertain=[]
    lines+=['Randomized interleaved complete-model timings','', 'These paired groups supersede fixed-process-order latency comparisons. Exact prior fidelity-tested artifact hashes are checked again; forward outputs are checked before timing. Dense/direct expert representations are simultaneously resident, with identical non-expert parameters shared, including every tied-weight alias. Their individual memory figures come from the earlier isolated runs. Three equal warmups and twenty paired groups per condition use seed4711 method-order shuffles. These are timing groups, not training replications.','', '| model / precision | context | forced tokens | dense prefill+generation median s | direct median s | direct−dense95%CI s | speed ratio | bounded verdict |','|---|---:|---|---:|---:|---|---:|---|']
    for case in data['results']:
        scope=case['kind']+'/'+case['precision'];quality=case['same_payload_NLL_equivalent_within_001'];records=[]
        for comparison in case['comparisons']:
            length=comparison['prompt_length'];forced=comparison['teacher_forced'];samples=[r for r in case['samples'] if r['prompt_length']==length and r['teacher_forced']==forced];dense=float(np.median([r['total_model_seconds'] for r in samples if r['mode']=='dense']));direct=float(np.median([r['total_model_seconds'] for r in samples if r['mode']=='direct']));ci=comparison['total_model_seconds_direct_minus_dense_ci']['ci95'];label=scope+'/context'+str(length)+'/forced'+str(forced)
            status='supported_in_tested_scope' if quality and ci[1]<0 else 'contradicted_in_tested_scope' if quality and ci[0]>0 else 'inconclusive';(positive if status.startswith('supported') else negative if status.startswith('contradicted') else uncertain).append(label)
            record={'scope':label,'status':status,'speed_ratio':dense/direct,'direct_minus_dense_ci':ci,'same_payload_quality_accepted':quality};records.append(record);lines.append(f"| {scope} | {length} | {forced} | {dense:.6f} | {direct:.6f} | {ci} | {dense/direct:.4f} | {status} |")
        summary.append({'scope':scope,'archive_sha256':case['archive_sha256'],'same_payload_NLL_delta':case['same_payload_full_NLL_delta'],'conditions':records});lines+=['',scope+' same-payload full-test NLL delta and95%CI: `'+str(case['same_payload_full_NLL_delta'])+'`; archive `'+case['archive_sha256']+'`. Original-model fidelity and training-quality tradeoffs are reported above for this exact archive.','']
    lines+=['','Granite uses its KV-cached32/128-context protocol; the learned native model recomputes32/96-token prefixes because it has no KV cache. Sixteen generated tokens, both greedy and identical-token teacher-forced workloads, include the complete model/routing/transforms/head and launch overhead. Final token D2H/hash remains excluded. Raw device times, TTFT, decode throughput, randomized orders, timestamps and generated-token hashes: '+evidence(path/'interleaved_runtime_results.json'),'']
    status='supported_in_tested_scope' if positive else 'contradicted_in_tested_scope' if negative and not uncertain else 'inconclusive'
    reason=('Resolved lower latency only in these declared conditions: '+', '.join(positive)+'. Other conditions and original-model quality tradeoffs remain separate; no universal inference claim.' if positive else 'No resolved complete-model acceleration in the declared interleaved conditions; see per-model/precision/workload intervals and same-payload fidelity. Negative verdict applies only where quality equivalence and higher latency resolve.' if status.startswith('contradicted') else 'Interleaved outcomes depend on model/precision/workload or do not resolve; individual negative/positive conditions and quality checks are retained.')
    verdict('E',status,reason,[path/'interleaved_runtime_results.json']);return {'cases':summary,'resolved_faster_conditions':positive,'resolved_slower_conditions':negative,'inconclusive_conditions':uncertain}
